// Noeud « Parser la tâche » — remplace queue.parse + queue.validate de Pentacore.
// Entrée : stdout de « Lire la queue » = "<chemin>\n<contenu>" (vide si queue vide).
const stdout = ($input.first().json.stdout || '').replace(/\r\n/g, '\n');
if (!stdout.trim()) return [{ json: { vide: true, valide: false, motif: 'queue vide' } }];

const saut = stdout.indexOf('\n');
const chemin = stdout.slice(0, saut).trim();
const contenu = stdout.slice(saut + 1);

const entete = (cle) => {
  const m = contenu.match(new RegExp(`^${cle}\\s*:\\s*(.+)$`, 'mi'));
  return m ? m[1].trim() : '';
};
// Une section court jusqu'au prochain ## BACK / ## UI seulement : les sous-titres
// ## Contexte, ## Etape… appartiennent à la section (queue._SECTION_RE).
const section = (nom) => {
  const re = /^##\s+(BACK|UI)\s*\n([\s\S]*?)(?=^##\s+(?:BACK|UI)\s*\n|$(?![\s\S]))/gm;
  for (const m of contenu.matchAll(re)) if (m[1] === nom) return m[2].trim();
  return '';
};

const slugEntete = entete('slug');
const slug = slugEntete || chemin.split('/').pop().replace(/\.md$/, '');
const back = section('BACK');
const demo = {};
for (const paire of entete('demo').split(',').filter(Boolean)) {
  const [cle, valeur] = paire.split('=').map((s) => s.trim());
  if (cle && valeur) demo[cle] = valeur;
}

let motif = '';
if (/^_\s*\(.*\)\s*_\s*[.,;:!]*$/s.test(back)) motif = 'section ## BACK reduite a un placeholder « _(aucun …)_ »';
else if (!back) motif = 'pas de section ## BACK (le palier 1 ne traite que la boucle backend)';
else if (!slugEntete) motif = `pas d'en-tete \`slug:\` (cloturerait sur chore(${slug}))`;
else if (!/^[a-z0-9-]+$/.test(slug)) motif = `slug \`${slug}\` hors alphabet [a-z0-9-] (devient un tag git)`;

return [{ json: { vide: false, valide: !motif, motif, chemin, slug, back, demo } }];

// Noeud « Arbre propre ? » — remplace git_safety.has_changes(ignore=TASK_FILES_RELATIVE).
// Entrée : stdout de `git status --porcelain --untracked-files=all`.
const IGNORES = ['.agents/queue/', '.agents/runs/'];
const residu = ($input.first().json.stdout || '')
  .split('\n')
  .filter((ligne) => ligne.trim())
  .map((ligne) => ligne.slice(3).trim())
  .filter((chemin) => !IGNORES.some((d) => chemin.startsWith(d)));
return [{ json: { propre: residu.length === 0, residu } }];

// Noeud « Préparer le contexte » — remplace orchestrator._contexte_cycle et
// _message_dispatch : le moteur prépare tout ce que l'agent doit savoir, l'agent
// ne reconstruit rien et n'écrit QUE son rapport, au chemin désigné.
const tache = $('Parser la tâche').first().json;
const [tag, base] = ($('Poser le tag').first().json.stdout || '').trim().split('\n');
const etat = $input.first().json;
const tentative = Number(etat.tentative || 1);
const constats = etat.constats || [];
const stage = 'backend-lead';

const horodatage = () => {
  const d = new Date();
  const p = (n) => String(n).padStart(2, '0');
  return `${d.getFullYear()}${p(d.getMonth() + 1)}${p(d.getDate())}-${p(d.getHours())}${p(d.getMinutes())}${p(d.getSeconds())}`;
};
const jeton = () => Math.floor(Math.random() * 0x10000).toString(16).padStart(4, '0');
const run_id = etat.run_id || `${tache.slug}-${horodatage()}-${jeton()}`;

const dossier = `.agents/runs/${run_id}`;
const chemin_contexte = `${dossier}/${stage}.context.json`;
const chemin_rapport = `${dossier}/${stage}.report.json`;

const contexte = {
  run: run_id, stage, tentative, slug: tache.slug,
  tache: { fichier: tache.chemin, slug: tache.slug, bloc: '## BACK', contenu: tache.back },
  perimetre: { tag, base, plage: `${base}..HEAD` },
  constats_ouverts: constats,
  rapports_pertinents: [],
  preuves_valides: [],
  rapport: {
    chemin: chemin_rapport, format: 'json',
    champs: ['run', 'stage', 'tentative', 'statut', 'resume', 'changements',
      'verifications', 'preuves', 'constats_ouverts', 'decisions'],
  },
};
if (tentative > 1) {
  contexte.reprise = true;
  contexte.constats_a_reprendre = constats;
}

const corps = tentative > 1
  ? `REPRISE CIBLEE du cycle \`${tache.slug}\` : corrige UNIQUEMENT les constats listes dans `
    + '`constats_a_reprendre` de ton contexte — chacun porte sa preuve. Le travail deja livre est '
    + 'conserve : ne refais pas la tache, ne revois pas les choix actes.'
  : `C'est LA tache dispatchee pour ce cycle (\`${tache.slug}\`, bloc ## BACK) : ne va pas en `
    + "chercher une autre dans la queue — ton contexte contient deja le bon bloc.";
const message = [
  `Contexte prepare : ${chemin_contexte}`,
  "Lis-le d'abord : il contient ta tache exacte, ton perimetre Git resolu et le chemin EXACT de ton rapport.",
  corps,
  `RAPPORT (OBLIGATOIRE) : ecris ton rapport dans \`${chemin_rapport}\` (JSON). Recopie \`run\`, `
    + `\`stage\` et \`tentative\` (= ${tentative}) depuis ton contexte ; renseigne \`statut\` `
    + '("ok", "partiel" ou "bloque"), `resume` (1-3 phrases), puis `changements`, `verifications`, '
    + '`preuves`, `constats_ouverts`, `decisions`. Sans rapport valide, ton stage est refuse.',
].join('\n');

const b64 = (texte) => Buffer.from(texte, 'utf8').toString('base64');
return [{ json: {
  run_id, tentative, constats, stage,
  slug: tache.slug, tag,
  comportement: tache.demo?.[`${stage}#${tentative}`] || 'vrai',
  chemin_contexte,
  contexte_b64: b64(JSON.stringify(contexte, null, 2)),
  message_b64: b64(message),
} }];

// Noeud « skip_gate » — remplace pentacore/skip_gate.py, sans modèle.
// Entrée : stdout = `git diff <tag>` puis "__UNTRACKED__" et, pour chaque
// fichier non suivi, "__FICHIER__ <chemin>" suivi de son contenu.
// Ne regarde que les lignes AJOUTÉES ; un skip est justifié par le marqueur
// `pentacore-skip-ok:` sur la même ligne ou la ligne juste au-dessus.
const MOTIFS = [
  /\b(it|test|describe)\.skip\(/,
  /\b(it|test|describe)\.only\(/,
  /\b(xit|xtest|xdescribe)\(/,
  /@pytest\.mark\.skip\b/,
  /@pytest\.mark\.skipif\b/,
  /\bpytest\.skip\(/,
  /@unittest\.skip\b/,
];
const JUSTIFICATION = 'pentacore-skip-ok';

const sortie = ($input.first().json.stdout || '').replace(/\r\n/g, '\n');
const [diff, nonSuivis = ''] = sortie.split('__UNTRACKED__\n');

// fichier -> [{ ligne, texte }] des lignes ajoutées, numérotées dans le nouveau fichier.
const ajouts = {};
let courant = null;
let numero = 0;
for (const ligne of diff.split('\n')) {
  if (ligne.startsWith('+++ ')) {
    const p = ligne.slice(4).trim();
    courant = p.startsWith('b/') ? p.slice(2) : null;
    if (courant) ajouts[courant] = ajouts[courant] || [];
    continue;
  }
  const hunk = ligne.match(/^@@ -\d+(?:,\d+)? \+(\d+)(?:,\d+)? @@/);
  if (hunk) { numero = Number(hunk[1]); continue; }
  if (!courant) continue;
  if (ligne.startsWith('+')) { ajouts[courant].push({ ligne: numero, texte: ligne.slice(1) }); numero += 1; }
  else if (ligne.startsWith(' ')) numero += 1;
}
let fichier = null;
for (const ligne of nonSuivis.split('\n')) {
  const entete = ligne.match(/^__FICHIER__ (.+)$/);
  if (entete) { fichier = entete[1].trim(); ajouts[fichier] = []; continue; }
  if (fichier) ajouts[fichier].push({ ligne: ajouts[fichier].length + 1, texte: ligne });
}

const constats = [];
for (const [chemin, lignes] of Object.entries(ajouts)) {
  lignes.forEach(({ ligne, texte }, i) => {
    if (!MOTIFS.some((m) => m.test(texte))) return;
    const precedente = i > 0 && lignes[i - 1].ligne === ligne - 1 ? lignes[i - 1].texte : '';
    if (texte.includes(JUSTIFICATION) || precedente.includes(JUSTIFICATION)) return;
    constats.push({ fichier: chemin, ligne, texte: texte.trim() });
  });
}

return [{ json: {
  ok: constats.length === 0,
  constats,
  rapport: constats.length ? `${constats.length} skip(s) non justifie(s)` : 'aucun skip non justifie',
} }];

// Noeud « Préparer le retour » — version palier 1 de la reprise ciblée
// (orchestrator.run_reprise_ciblee) : le Lead reçoit les constats précis de la
// gate, avec leur preuve (fichier:ligne), et une tentative de plus.
const precedent = $('Préparer le contexte').first().json;
const constats = $input.first().json.constats.map(
  (c) => `skip_gate : ${c.fichier}:${c.ligne} : ${c.texte} — test desactive sans \`pentacore-skip-ok: <raison>\``);
return [{ json: { tentative: precedent.tentative + 1, run_id: precedent.run_id, constats } }];
